# -*- coding: utf-8 -*-
"""MANAPRINT — TRIPLE POWER 75 (création 2KEA) · maquette CANVA de Maeva (26/11/2026,
« triple_power_canva_10_A4_points »). Reprise TELLE QUELLE : 10 tickets / feuille A4 PORTRAIT
(5 colonnes x 2 rangées), traits de coupe en pointillés. Chaque ticket : cadre arrondi en
pointillés, « N° ___ », fleur, TRIPLE POWER et sa vague, 4 bulles OFF · ON · OFF · ON
(fixe, choix de Maeva 26/11 : B OFF, I ON, G OFF, O ON). Le dessin est rejoué TRAIT POUR
TRAIT depuis la maquette et rangé une seule fois par document (fichier léger) ; la fleur est
posée en pochoir (en couleur, MANAPRINT repeint le dessin, les chiffres restent noirs).
RÈGLE (inchangée) — 4 lignes, de haut en bas : B 1-15 · I 16-30 · G 46-60 · O 61-75 (pas de N).
   Une ligne = 3 numéros de sa plage, triés : le plus petit DANS la bulle (28 pt), le moyen
   à droite en haut (30 pt), le plus grand dessous (26 pt) — grossis le 26/11 (30 pt max).
   Sur une rangée de 5 tickets, chaque numéro d'une plage ne sort qu'une fois.
   Crieur : 1-30 et 46-75.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = A4
COLS, RANGS = 5, 2
CARTES_PAGE = COLS * RANGS                # 10
CELL_W, CELL_H = 119.0551, 420.9449
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM = "Helvetica-Bold"
LIGNES = "BIGO"
PLAGES = {"B": (1, 15), "I": (16, 30), "G": (46, 60), "O": (61, 75)}
# lignes de base (bulle, droite en haut, dessous) des 4 lignes, de haut en bas
BASES = [(270.0327, 287.1496, 264.4724), (189.5287, 206.6457, 183.9685),
         (109.0248, 126.1417, 103.4646), (28.52085, 45.6378, 22.96063)]
_XB, _XH, _XD = 30.04724, 90.14, 84.47   # centres : bulle, droite en haut, dessous
T_BULLE, T_HAUT, T_DESSOUS = 28, 30, 26     # grossis (Maeva 26/11)
_DB, _DH, _DD = -1.5, 2.0, -2.0          # décalage des lignes de base pour les gros chiffres

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _rangee(rng):
    """5 tickets : pour chaque plage, les 15 numéros répartis 3 par ticket (aucun doublon)."""
    r = None
    for _ in range(200):
        r = [{} for _ in range(5)]
        for k in LIGNES:
            a, b = PLAGES[k]
            t = list(range(a, b + 1))
            rng.shuffle(t)
            for i in range(5):
                r[i][k] = sorted(t[3 * i:3 * i + 3])
        cles = [tuple(tuple(r[i][k]) for k in LIGNES) for i in range(5)]
        if not any(cl in _DEJA for cl in cles):
            _DEJA.update(cles)
            return r
    return r


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_tpow_modele", False):
        return
    av, ap = _DESSIN_AVANT, _DESSIN_APRES
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        av = av.replace(k, c._doc.getInternalFontName(v))
        ap = ap.replace(k, c._doc.getInternalFontName(v))
    import base64
    c.beginForm("TRIPLE_POWER", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + av)
    _masque.poser(c, "TPOW_FLEUR", base64.b64decode(_FLEUR_PNG),
                  7.086614, 331.6535, 37.39737, 32.59843)
    c._code.append(ap + "\nQ")
    c.endForm()
    c._tpow_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("TRIPLE_POWER")
    _txt(c, "%06d" % serie, 70.09543, 395.4331, "Helvetica", 10, NOIR)
    for (yb, yh, yd), k in zip(BASES, LIGNES):
        a, b, d = nums[k]
        _txt(c, str(a), _XB, yb + _DB, POLICE_NUM, T_BULLE, col, centre=True)
        _txt(c, str(b), _XH, yh + _DH, POLICE_NUM, T_HAUT, col, centre=True)
        _txt(c, str(d), _XD, yd + _DD, POLICE_NUM, T_DESSOUS, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_tickets if nb_tickets is not None else nb_cartes
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("TRIPLE POWER 75")
    rng = random.Random(int(serie_start) * 100003 + 7577)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)

        tirage = _rangee(rng) + _rangee(rng)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, tirage[idx], col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


